+static void
+wmem_test_utf8buf(void)
+{
+    wmem_allocator_t   *allocator;
+    wmem_u8buf_t      *strbuf;
+    int                 i;
+    char               *str;
+
+    allocator = wmem_allocator_new(WMEM_ALLOCATOR_STRICT);
+
+    strbuf = wmem_u8buf_new(allocator, "TEST");
+    g_assert_nonnull(strbuf);
+    g_assert_cmpstr(wmem_u8buf_get_str(strbuf), ==, "TEST");
+    g_assert_cmpuint(wmem_u8buf_get_codelen(strbuf), ==, 4);
+    g_assert_cmpuint(wmem_u8buf_get_bytelen(strbuf), ==, 4);
+
+    wmem_u8buf_append(strbuf, "FUZZ");
+    g_assert_cmpstr(wmem_u8buf_get_str(strbuf), ==, "TESTFUZZ");
+    g_assert_cmpuint(wmem_u8buf_get_codelen(strbuf), ==, 8);
+    g_assert_cmpuint(wmem_u8buf_get_bytelen(strbuf), ==, 8);
+
+    wmem_u8buf_append_printf(strbuf, "%d%s", 3, "a");
+    g_assert_cmpstr(wmem_u8buf_get_str(strbuf), ==, "TESTFUZZ3a");
+    g_assert_cmpuint(wmem_u8buf_get_codelen(strbuf), ==, 10);
+    g_assert_cmpuint(wmem_u8buf_get_bytelen(strbuf), ==, 10);
+
+    wmem_u8buf_append_c(strbuf, 'q');
+    g_assert_cmpstr(wmem_u8buf_get_str(strbuf), ==, "TESTFUZZ3aq");
+    g_assert_cmpuint(wmem_u8buf_get_codelen(strbuf), ==, 11);
+    g_assert_cmpuint(wmem_u8buf_get_bytelen(strbuf), ==, 11);
+
+    wmem_u8buf_append_unichar(strbuf, g_utf8_get_char("\xC2\xA9"));
+    g_assert_cmpstr(wmem_u8buf_get_str(strbuf), ==, "TESTFUZZ3aq\xC2\xA9");
+    g_assert_cmpuint(wmem_u8buf_get_codelen(strbuf), ==, 12);
+    g_assert_cmpuint(wmem_u8buf_get_bytelen(strbuf), ==, 13);
+
+    wmem_u8buf_truncate(strbuf, 32);
+    wmem_u8buf_truncate(strbuf, 24);
+    wmem_u8buf_truncate(strbuf, 16);
+    wmem_u8buf_truncate(strbuf, 13);
+    g_assert_cmpstr(wmem_u8buf_get_str(strbuf), ==, "TESTFUZZ3aq\xC2\xA9");
+    g_assert_cmpuint(wmem_u8buf_get_codelen(strbuf), ==, 12);
+    g_assert_cmpuint(wmem_u8buf_get_bytelen(strbuf), ==, 13);
+
+    wmem_u8buf_truncate(strbuf, 3);
+    g_assert_cmpstr(wmem_u8buf_get_str(strbuf), ==, "TES");
+    g_assert_cmpuint(wmem_u8buf_get_codelen(strbuf), ==, 3);
+    g_assert_cmpuint(wmem_u8buf_get_bytelen(strbuf), ==, 3);
+
+    wmem_u8buf_append_len(strbuf, "TFUZZ1234", 5);
+    g_assert_cmpstr(wmem_u8buf_get_str(strbuf), ==, "TESTFUZZ");
+    g_assert_cmpuint(wmem_u8buf_get_codelen(strbuf), ==, 8);
+    g_assert_cmpuint(wmem_u8buf_get_bytelen(strbuf), ==, 8);
+
+    strbuf = wmem_u8buf_new_sized(allocator, 10, 10);
+    g_assert_nonnull(strbuf);
+    g_assert_cmpstr(wmem_u8buf_get_str(strbuf), ==, "");
+    g_assert_cmpuint(wmem_u8buf_get_codelen(strbuf), ==, 0);
+    g_assert_cmpuint(wmem_u8buf_get_bytelen(strbuf), ==, 0);
+
+    wmem_u8buf_append(strbuf, "FUZZ");
+    g_assert_cmpstr(wmem_u8buf_get_str(strbuf), ==, "FUZZ");
+    g_assert_cmpuint(wmem_u8buf_get_codelen(strbuf), ==, 4);
+    g_assert_cmpuint(wmem_u8buf_get_bytelen(strbuf), ==, 4);
+
+    wmem_u8buf_append_printf(strbuf, "%d%s", 3, "abcd");
+    g_assert_cmpstr(wmem_u8buf_get_str(strbuf), ==, "FUZZ3abcd");
+    g_assert_cmpuint(wmem_u8buf_get_codelen(strbuf), ==, 9);
+    g_assert_cmpuint(wmem_u8buf_get_bytelen(strbuf), ==, 9);
+
+    // Ok
+    wmem_u8buf_append_unichar(strbuf, g_utf8_get_char("\xC2\xA9"));
+    g_assert_cmpstr(wmem_u8buf_get_str(strbuf), ==, "FUZZ3abcd\xC2\xA9");
+    g_assert_cmpuint(wmem_u8buf_get_codelen(strbuf), ==, 10);
+    g_assert_cmpuint(wmem_u8buf_get_bytelen(strbuf), ==, 11);
+
+    // No room
+    wmem_u8buf_append_unichar(strbuf, g_utf8_get_char("\xC2\xA9"));
+    g_assert_cmpstr(wmem_u8buf_get_str(strbuf), ==, "FUZZ3abcd\xC2\xA9");
+    g_assert_cmpuint(wmem_u8buf_get_codelen(strbuf), ==, 10);
+    g_assert_cmpuint(wmem_u8buf_get_bytelen(strbuf), ==, 11);
+
+    str = wmem_u8buf_finalize(strbuf);
+    g_assert_cmpstr(str, ==, "FUZZ3abcd\xC2\xA9");
+    g_assert_cmpuint(g_utf8_strlen(str, -1), ==, 10);
+
+    wmem_free_all(allocator);
+
+    strbuf = wmem_u8buf_new(allocator, "TEST");
+    for (i=0; i<1024; i++) {
+        if (g_test_rand_bit()) {
+            wmem_u8buf_append(strbuf, "ABC");
+        }
+        else {
+            wmem_u8buf_append_printf(strbuf, "%d%d", 3, 777);
+        }
+        wmem_strict_check_canaries(allocator);
+    }
+    g_assert_true(strlen(wmem_u8buf_get_str(strbuf)) ==
+             wmem_u8buf_get_codelen(strbuf));
+
+    wmem_destroy_allocator(allocator);
+}

